  const reviewSummary=useMemo(()=>{if(!data)return {due:0,news:0,todayReviews:0};const queue=buildReviewQueue(data);return {due:queue.filter(task=>!task.isNew).length,news:queue.filter(task=>task.isNew).length,todayReviews:data.stats.reviews.filter(record=>sameDay(record.time)).length};},[data?.entries,data?.settings,data?.stats.reviews,reviewMinute]);
